9	pub fn constant_evaluate<'a>(
10	    e: Node,
11	    expr_arena: &'a Arena<AExpr>,
12	    _schema: &Schema,
13	    _depth: usize,
14	) -> Option<Option<Cow<'a, LiteralValue>>> {
15	    match expr_arena.get(e) {
16	        AExpr::Literal(lv) => Some(Some(Cow::Borrowed(lv))),
17	        _ => {
18	            if aexpr_to_leaf_names_iter(e, expr_arena).next().is_none() {
19	                Some(None)
20	            } else {
21	                None
22	            }
23	        },
24	    }
25	}
