85	impl DynListLiteralValue {
86	    pub fn try_materialize_to_dtype(
87	        self,
88	        dtype: &DataType,
89	        options: CastOptions,
90	    ) -> PolarsResult<Scalar> {
91	        let Some(inner_dtype) = dtype.inner_dtype() else {
92	            polars_bail!(InvalidOperation: "conversion from list literal to `{dtype}` failed.");
93	        };
94	
95	        let s = match self {
96	            DynListLiteralValue::Str(vs) => {
97	                StringChunked::from_iter_options(get_literal_name(), vs.into_iter()).into_series()
98	            },
99	            DynListLiteralValue::Int(vs) => {
100	                #[cfg(feature = "dtype-i128")]
101	                {
102	                    Int128Chunked::from_iter_options(get_literal_name(), vs.into_iter())
103	                        .into_series()
104	                }
105	
106	                #[cfg(not(feature = "dtype-i128"))]
107	                {
108	                    Int64Chunked::from_iter_options(
109	                        get_literal_name(),
110	                        vs.into_iter().map(|v| v.map(|v| v as i64)),
111	                    )
112	                    .into_series()
113	                }
114	            },
115	            DynListLiteralValue::Float(vs) => {
116	                Float64Chunked::from_iter_options(get_literal_name(), vs.into_iter()).into_series()
117	            },
118	            DynListLiteralValue::List(_) => todo!("nested lists"),
119	        };
120	
121	        let s = s.cast_with_options(inner_dtype, options)?;
122	        let value = match dtype {
123	            DataType::List(_) => AnyValue::List(s),
124	            #[cfg(feature = "dtype-array")]
125	            DataType::Array(_, size) => AnyValue::Array(s, *size),
126	            _ => unreachable!(),
127	        };
128	
129	        Ok(Scalar::new(dtype.clone(), value))
130	    }
131	}
