294	    pub fn to_any_value(&self) -> Option<AnyValue<'_>> {
295	        let av = match self {
296	            Self::Scalar(sc) => sc.value().clone(),
297	            Self::Range(range) => {
298	                let s = range.clone().try_materialize_to_series(&range.dtype).ok()?;
299	                AnyValue::List(s)
300	            },
301	            Self::Series(_) => return None,
302	            Self::Dyn(d) => match d {
303	                DynLiteralValue::Int(v) => materialize_dyn_int(*v),
304	                DynLiteralValue::Float(v) => AnyValue::Float64(*v),
305	                DynLiteralValue::Str(v) => AnyValue::String(v),
306	                DynLiteralValue::List(_) => todo!(),
307	            },
308	        };
309	        Some(av)
310	    }
